var input = $input.first().json;
if (input.cachedStatus === 'complete' && input.cachedResponseJson) {
  try {
    return [{ json: JSON.parse(input.cachedResponseJson) }];
  } catch (e) {}
}
return [{ json: {
  requestId: input.requestId, category: input.category, businessName: input.businessName,
  status: 'processing', demo: true,
  message: 'This approval is already being processed. Please wait a moment and check again.'
} }];

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

const requestId = body.requestId || ('build-' + Date.now());
const category = String(body.category || '').toLowerCase().trim();
const businessName = String(body.businessName || '').trim();
const mode = body.mode === 'deep' ? 'deep' : 'standard';
const selectedOpportunities = Array.isArray(body.selectedOpportunities) ? body.selectedOpportunities : [];
const approvedBy = String(body.approvedBy || '').trim() || 'the approver';
const approvedAt = new Date().toISOString();
const contactEmail = body.contactEmail || '';
const currentTools = body.currentTools || '';
const scale = body.scale || '';
const integrationNeeds = body.integrationNeeds || '';
const diagnosticFinding = body.diagnosticFinding && typeof body.diagnosticFinding === 'object' ? body.diagnosticFinding : {};
const clientIp = String(headers['x-forwarded-for'] || '').split(',')[0].trim();

const missingFields = !businessName || !category || selectedOpportunities.length === 0;

return [{ json: {
  requestId: requestId, category: category, businessName: businessName, mode: mode,
  selectedOpportunities: selectedOpportunities, approvedBy: approvedBy, approvedAt: approvedAt,
  contactEmail: contactEmail, currentTools: currentTools, scale: scale,
  integrationNeeds: integrationNeeds, diagnosticFinding: diagnosticFinding, clientIp: clientIp, missingFields: missingFields
} }];

const orig = $('Normalize & Validate').first().json;
const rows = $input.all().map(item => item.json);
const dupRow = rows.find(r => r.request_id && r.request_id === orig.requestId && r.stage === 'approve');
return [{ json: {
  requestId: orig.requestId, category: orig.category, businessName: orig.businessName, mode: orig.mode,
  selectedOpportunities: orig.selectedOpportunities, approvedBy: orig.approvedBy, approvedAt: orig.approvedAt,
  contactEmail: orig.contactEmail, currentTools: orig.currentTools, scale: orig.scale, integrationNeeds: orig.integrationNeeds,
  diagnosticFinding: orig.diagnosticFinding,
  isDuplicate: !!dupRow,
  cachedStatus: dupRow ? dupRow.status : '',
  cachedResponseJson: dupRow ? dupRow.response_json : ''
} }];

const input = $('Evaluate Duplicate').first().json;
const TEMPLATE_LIBRARY = {
  eatery: {
    name: 'Order and Reservation Confirmation',
    trigger: 'A new order or reservation is submitted through the ordering/reservation form',
    steps: [
      'The automation receives the order or reservation details from the form',
      'It checks required fields are present and flags incomplete submissions to staff',
      'It writes the validated order to the order record',
      'It sends the customer a confirmation with their order or reservation details'
    ],
    integrations: ['Order/reservation form', 'Order record', 'Customer email'],
    builtOn: 'n8n',
    categoryEducation: [
      { current_activity: 'Staff manually take down orders and reservations', how_automation_helps: 'Orders and reservations are captured and confirmed automatically', business_benefit: 'Fewer missed or mixed-up orders' },
      { current_activity: 'Customers are updated by phone or in person only', how_automation_helps: 'Customers get an automatic confirmation with their order details', business_benefit: 'Customers feel informed without staff chasing them' },
      { current_activity: 'No easy record of past orders', how_automation_helps: 'Every order is recorded automatically', business_benefit: 'Easy to look back and resolve questions' }
    ],
    simple: true
  },
  law_firm: {
    name: 'Client Intake and Confirmation',
    trigger: 'A new client inquiry is submitted through the intake form',
    steps: [
      'The automation receives the client inquiry details from the intake form',
      'It checks required fields are present and flags incomplete inquiries to staff',
      'It writes the validated inquiry to the case record',
      'It sends the client a confirmation that their inquiry was received'
    ],
    integrations: ['Intake form', 'Case record', 'Client email'],
    builtOn: 'n8n',
    categoryEducation: [
      { current_activity: 'Staff manually log new client inquiries', how_automation_helps: 'Inquiries are captured and logged automatically as they come in', business_benefit: 'Nothing gets missed or delayed' },
      { current_activity: 'Clients wait to hear back that their inquiry was received', how_automation_helps: 'Clients get an automatic confirmation the moment they reach out', business_benefit: 'Clients feel reassured immediately' },
      { current_activity: 'No central record of every inquiry', how_automation_helps: 'Every inquiry is recorded automatically', business_benefit: 'Easy to track and follow up' }
    ],
    simple: true
  },
  salon_beauty: {
    name: 'Booking Confirmation',
    trigger: 'A new booking request is submitted through the booking form',
    steps: [
      'The automation receives the booking request details from the form',
      'It checks required fields are present and flags incomplete bookings to staff',
      'It writes the validated booking to the booking record',
      'It sends the client a confirmation of their booking details'
    ],
    integrations: ['Booking form', 'Booking record', 'Client email'],
    builtOn: 'n8n',
    categoryEducation: [
      { current_activity: 'Staff manually take bookings over the phone or in person', how_automation_helps: 'Bookings are captured and confirmed automatically', business_benefit: 'Fewer double-bookings and mix-ups' },
      { current_activity: "Clients are not always sure their booking went through", how_automation_helps: 'Clients get an automatic confirmation with their booking details', business_benefit: "Clients feel confident their appointment is set" },
      { current_activity: 'No easy record of past bookings', how_automation_helps: 'Every booking is recorded automatically', business_benefit: 'Easy to check history and resolve questions' }
    ],
    simple: true
  },
  logistics: {
    name: 'Dispatch Capture and Confirmation',
    trigger: 'A new dispatch or order is submitted through the order form',
    steps: [
      'The automation receives the dispatch details from the order form',
      'It checks required fields are present and flags incomplete dispatches to staff',
      'It writes the validated dispatch to the dispatch record',
      'It sends the customer a confirmation with their reference and expected timeline'
    ],
    integrations: ['Order form', 'Dispatch record', 'Customer email'],
    builtOn: 'n8n',
    categoryEducation: [
      { current_activity: 'Staff manually re-enter order or dispatch details', how_automation_helps: 'Order details are captured and recorded automatically', business_benefit: 'Fewer mistakes and faster processing' },
      { current_activity: 'Customers are told about updates only when someone remembers', how_automation_helps: 'A confirmation and reference number go out automatically', business_benefit: 'Customers feel informed without staff chasing updates' },
      { current_activity: 'No single place to check what happened with an order', how_automation_helps: 'Every order is recorded automatically in one place', business_benefit: 'Easy to answer customer questions' }
    ],
    simple: true
  }
};
const template = TEMPLATE_LIBRARY[input.category] || null;
const isDeepMode = input.mode === 'deep';
const templateMatched = !isDeepMode && !!template && !!template.simple;
return [{ json: {
  requestId: input.requestId, category: input.category, businessName: input.businessName,
  contactName: input.contactName, contactRole: input.contactRole, mode: input.mode,
  selectedOpportunities: input.selectedOpportunities, approvedBy: input.approvedBy, approvedAt: input.approvedAt,
  contactEmail: input.contactEmail, currentTools: input.currentTools, scale: input.scale, integrationNeeds: input.integrationNeeds,
  diagnosticFinding: input.diagnosticFinding,
  templateMatched: templateMatched, template: template
} }];

const input = $input.first().json;
const t = input.template;
const automationName = t.name + ' -- ' + input.businessName;
return [{ json: {
  requestId: input.requestId, category: input.category, businessName: input.businessName, mode: input.mode,
  status: 'demo-build-ready', demo: true,
  automationName: automationName,
  opportunityBuilt: t.name,
  trigger: t.trigger,
  steps: t.steps,
  integrations: t.integrations,
  builtOn: t.builtOn,
  categoryEducation: t.categoryEducation,
  diagnosticFinding: input.diagnosticFinding,
  selectedOpportunities: input.selectedOpportunities,
  approvedBy: input.approvedBy, approvedAt: input.approvedAt,
  developerNotes: ['This automation runs in n8n. A developer can access the workflow in the LordGen n8n workspace, export it, and connect it to your real ' + t.integrations[0].toLowerCase() + ' and ' + t.integrations[1].toLowerCase() + ' before going live.'],
  contactEmail: input.contactEmail
} }];

const input = $input.first().json;
return [{ json: {
  requestId: input.requestId, category: input.category, businessName: input.businessName, mode: input.mode,
  status: 'developer_review', demo: true,
  message: input.mode === 'deep' ? 'This request needs custom developer work beyond our ready-made automations, as expected for Deep Diagnostic.' : 'No ready-made automation matched this opportunity yet -- a developer will review and build this.',
  selectedOpportunities: input.selectedOpportunities,
  diagnosticFinding: input.diagnosticFinding,
  context: { currentTools: input.currentTools, scale: input.scale, integrationNeeds: input.integrationNeeds },
  approvedBy: input.approvedBy, approvedAt: input.approvedAt,
  contactEmail: input.contactEmail
} }];

const row = $input.first().json;
try {
  return [{ json: JSON.parse(row.response_json) }];
} catch (e) {
  return [{ json: { error: 'response_serialization_failed', requestId: row.request_id } }];
}

